package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.widget.Toast;import java.net.*;import java.io.*;import java.security.*;import org.json.*;
/** Official HTTPS updates; installs always use Android's package confirmation. */
final class OfficialUpdate {
 static final String BASE="https://morph-tv.com/";private static boolean checking,downloading;private static JSONObject available;
 static String normalized(String value){java.util.regex.Matcher m=java.util.regex.Pattern.compile("^(\\d+)\\.(\\d+)\\.(\\d+)").matcher(value==null?"":value);return m.find()?m.group(1)+"."+m.group(2)+"."+m.group(3):"0.0.0";}
 static int compare(String a,String b){String[] x=normalized(a).split("\\."),y=normalized(b).split("\\.");for(int i=0;i<3;i++){long u=Long.parseLong(x[i]),v=Long.parseLong(y[i]);if(u!=v)return u<v?-1:1;}return 0;}
 static boolean allowed(Activity a,String file,String version){if(!version.matches("[0-9]+\\.[0-9]+\\.[0-9]+"))return false;String name=a.getPackageName().equals("local.morph.iptv")?"Morph-IPTV-Android-TV":a.getPackageName().equals("local.tvmorph.tv")?"Morph-TV-Android-TV":a.getPackageName().equals("local.cleartv.mobile")?"Morph-TV-Phone":"";return !name.isEmpty()&&(file.equals(name+"-"+version+".apk")||name.equals("Morph-TV-Android-TV")&&file.equals("Morph-Launcher-"+version+".apk"));}
 private static String own(Activity a)throws Exception{return a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionName;}
 private static HttpURLConnection connection(String path)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(BASE+path).openConnection();c.setRequestProperty("User-Agent","MorphTV/Updates");c.setRequestProperty("Accept-Encoding","identity");c.setConnectTimeout(6000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);if(c.getResponseCode()!=200){c.disconnect();throw new IOException("Update download unavailable");}return c;}
 private static JSONObject release(Activity a)throws Exception{HttpURLConnection c=connection("catalog.json");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>524288)throw new IOException("Catalog too large");out.write(b,0,n);}JSONObject catalog=new JSONObject(out.toString("UTF-8")),best=null;JSONArray all=catalog.getJSONArray("releases");for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);String file=item.optString("file"),version=item.optString("version",catalog.optString("latest"));if(allowed(a,file,version)&&item.optString("sha256").matches("[a-fA-F0-9]{64}")&&(best==null||compare(version,best.getString("version"))>0))best=new JSONObject(item.toString()).put("version",version);}if(best==null)throw new IOException("No update published for this application");return best;}finally{c.disconnect();}}
 static synchronized void check(Activity a,boolean manual){if(checking||downloading)return;checking=true;new Thread(()->{JSONObject latest=null;Exception failure=null;try{android.content.SharedPreferences p=a.getSharedPreferences("official-update",0);String cached=p.getString("release","");if(!manual&&!cached.isEmpty()&&System.currentTimeMillis()-p.getLong("checked",0)<86400000L)latest=new JSONObject(cached);else{latest=release(a);p.edit().putString("release",latest.toString()).putLong("checked",System.currentTimeMillis()).apply();}if(compare(latest.getString("version"),own(a))<=0)latest=null;}catch(Exception e){failure=e;}final JSONObject result=latest;final Exception error=failure;synchronized(OfficialUpdate.class){available=result;checking=false;}a.runOnUiThread(()->{if(a.isFinishing())return;String data=result==null?"{}":result.toString();if(a instanceof TvActivity)((TvActivity)a).updateResult(data);if(error!=null){if(manual)message(a,UiSettings.text(a,"تعذر فحص التحديث. تأكد من الإنترنت وحاول مرة أخرى.","Could not check for updates. Check Internet and retry."));return;}if(result==null){if(manual)message(a,UiSettings.text(a,"أنت تستخدم أحدث إصدار متاح.","You have the latest available version."));return;}if(manual){download(a,result);return;}android.content.SharedPreferences p=a.getSharedPreferences("official-update",0);if(a.hasWindowFocus()&&!p.getString("offered","").equals(result.optString("version"))){p.edit().putString("offered",result.optString("version")).apply();offer(a,result);}});},"morph-update-check").start();}
 private static void offer(Activity a,JSONObject item){new AlertDialog.Builder(a).setTitle(UiSettings.text(a,"تحديث متاح · ","Update available · ")+item.optString("version")).setMessage(UiSettings.text(a,"نزّل تحديث التطبيق من المصدر الرسمي. بياناتك وثيماتك محفوظة. بعد التحميل ستظهر موافقة التثبيت من أندرويد.","Download the app update from the official source. Your settings and themes are preserved. Android will ask you to confirm installation after downloading.")).setPositiveButton(UiSettings.text(a,"تحميل التحديث","Download update"),(d,w)->download(a,item)).setNegativeButton(UiSettings.text(a,"لاحقًا","Later"),null).show();}
 private static synchronized void download(Activity a,JSONObject item){if(downloading||!TvUpdater.reserveOfficial())return;downloading=true;final java.util.concurrent.atomic.AtomicBoolean cancelled=new java.util.concurrent.atomic.AtomicBoolean();final ProgressDialog progress=new ProgressDialog(a);progress.setTitle(UiSettings.text(a,"تحديث التطبيق","App update"));progress.setMessage(UiSettings.text(a,"جاري تحميل التحديث…","Downloading update…"));progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(false);progress.setButton(android.content.DialogInterface.BUTTON_NEGATIVE,UiSettings.text(a,"إلغاء","Cancel"),(d,w)->cancelled.set(true));progress.show();Toast.makeText(a,UiSettings.text(a,"جاري تحميل تحديث التطبيق…","Downloading app update…"),Toast.LENGTH_LONG).show();new Thread(()->{File partial=new File(a.getCacheDir(),"official-update-partial.apk");HttpURLConnection c=null;try{String file=item.getString("file");if(!allowed(a,file,item.getString("version")))throw new IOException("Invalid file");c=connection(file);MessageDigest digest=MessageDigest.getInstance("SHA-256");long deadline=System.nanoTime()+900000000000L;int total=0,lastPercent=-1;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(partial)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(cancelled.get()||System.nanoTime()>deadline||(total+=n)>268435456)throw new IOException("Download limit");digest.update(b,0,n);out.write(b,0,n);final int percent=(int)Math.min(100,total*100L/Math.max(1,item.optLong("bytes",1)));if(percent!=lastPercent){lastPercent=percent;a.runOnUiThread(()->{if(!a.isFinishing())progress.setProgress(percent);});}}}StringBuilder hash=new StringBuilder();for(byte x:digest.digest())hash.append(String.format(java.util.Locale.US,"%02x",x&255));if(item.optLong("bytes",-1)!=total||!hash.toString().equalsIgnoreCase(item.getString("sha256")))throw new IOException("Update checksum rejected");TvUpdater.verify(a,partial);android.content.pm.PackageInfo info=a.getPackageManager().getPackageArchiveInfo(partial.getAbsolutePath(),0);if(info==null||!item.getString("version").equals(normalized(info.versionName)))throw new IOException("Update version rejected");File verified=new File(a.getCacheDir(),"verified-update.apk");if(verified.exists()&&!verified.delete()||!partial.renameTo(verified))throw new IOException("Could not stage update");a.runOnUiThread(()->{if(!cancelled.get()&&!a.isFinishing())TvUpdater.installVerified(a);});}catch(Exception e){partial.delete();if(!cancelled.get())a.runOnUiThread(()->message(a,UiSettings.text(a,"تعذر تحميل تحديث موثوق. راجع الإنترنت والمساحة المتاحة ثم أعد المحاولة.","Could not download a verified update. Check Internet and free storage, then retry.")));}finally{a.runOnUiThread(()->{if(progress.isShowing())progress.dismiss();});if(c!=null)c.disconnect();TvUpdater.releaseOfficial();synchronized(OfficialUpdate.class){downloading=false;}}},"morph-update-download").start();}
 private static void message(Activity a,String text){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle(a.getApplicationInfo().loadLabel(a.getPackageManager())).setMessage(text).setPositiveButton("OK",null).show();}
}
